/* =====================================================================
   KICKS（SneakerMarket）一般商城模組 — 假資料
   負責人：郁涵（一般商城模組）
   產生日期：2026-09-27（由 SneakerMarketDB 現行資料匯出後整理）

   執行說明：
     1. 請先執行 commerce_schema.sql 建好資料表，再執行本檔。
     2. 本檔保留原本的 id（使用 IDENTITY_INSERT），
        因為競標模組的假資料也會用到 brand_id、category_id，id 不可變動。
     3. 整份包在一個交易（transaction）裡：中途任何一筆失敗，
        全部自動還原，不會留下匯入一半的資料，修正後可直接重跑。
     4. 中文字串皆加上 N 前綴，避免中文變成問號。

   包含資料：
     brands            14 筆
     categories         4 筆
     cvs_stores       106 筆
     products          62 筆
     product_variants 683 筆
     product_images    62 筆

   刻意不含資料的表：carts、cart_items、orders、order_items
     原因：這 4 張表的資料都綁定 member_id（會員編號）。
     Demo 電腦的會員會重新註冊、編號從頭開始，
     若帶入舊的測試訂單與購物車，會掛到新註冊的會員名下，造成錯誤顯示。
     Demo 時請現場註冊會員並下單，訂單與購物車會自動產生。
   ===================================================================== */

SET NOCOUNT ON;
SET XACT_ABORT ON;   -- 任何錯誤都讓整個交易還原

BEGIN TRANSACTION;


/* ---------------------------------------------------------------------
   1. brands：品牌主檔（跨模組共用；id 1~14 連續編號，1~5 為原始品牌，6~14 為後來新增）
   共 14 筆
   --------------------------------------------------------------------- */
SET IDENTITY_INSERT brands ON;
SET IDENTITY_INSERT brands OFF;

/* ---------------------------------------------------------------------
   2. categories：球鞋分類主檔（跨模組共用）
   共 4 筆
   --------------------------------------------------------------------- */
SET IDENTITY_INSERT categories ON;
SET IDENTITY_INSERT categories OFF;

/* ---------------------------------------------------------------------
   3. cvs_stores：7-11 門市資料（含經緯度，地圖選店用）
   共 106 筆
   --------------------------------------------------------------------- */
SET IDENTITY_INSERT cvs_stores ON;
SET IDENTITY_INSERT cvs_stores OFF;

/* ---------------------------------------------------------------------
   4. products：商品主檔
   共 62 筆
   --------------------------------------------------------------------- */
SET IDENTITY_INSERT products ON;
SET IDENTITY_INSERT products OFF;

/* ---------------------------------------------------------------------
   5. product_variants：商品規格（尺寸、價格、庫存；sku 為 NULL 表示該規格未設定貨號）
   共 683 筆
   --------------------------------------------------------------------- */
SET IDENTITY_INSERT product_variants ON;
SET IDENTITY_INSERT product_variants OFF;

/* ---------------------------------------------------------------------
   6. product_images：商品圖片（路徑皆為 /images/products/，圖片檔隨 Git 一起提供）
   共 62 筆
   --------------------------------------------------------------------- */
SET IDENTITY_INSERT product_images ON;
SET IDENTITY_INSERT product_images OFF;

COMMIT TRANSACTION;

/* ---------------------------------------------------------------------
   匯入後檢查：筆數應為 14 / 4 / 106 / 62 / 683 / 62
   --------------------------------------------------------------------- */
SELECT 'brands' AS 資料表, COUNT(*) AS 筆數 FROM brands
UNION ALL SELECT 'categories',       COUNT(*) FROM categories
UNION ALL SELECT 'cvs_stores',       COUNT(*) FROM cvs_stores
UNION ALL SELECT 'products',         COUNT(*) FROM products
UNION ALL SELECT 'product_variants', COUNT(*) FROM product_variants
UNION ALL SELECT 'product_images',   COUNT(*) FROM product_images;