INSERT INTO products (product_id, brand_id, category_id, product_name, description, status, created_at, updated_at) VALUES
                                                                                                                        (1, 2, 1, N'Air Jordan 1 Retro High OG "Lost & Found"', N'Air Jordan 1 以 1985 年的芝加哥配色為本，做舊的米黃中底與皮革鞋面，重現老鞋店倉庫裡的原封庫存，經典永不退流行。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (2, 2, 1, N'Air Jordan 3 Retro OG "Black Cement"', N'1988 年首次將爆裂紋與可視氣墊帶進 Jordan 系列。黑色皮革搭配灰色爆裂紋，後跟 Nike Air 標誌重現原版設計。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (3, 2, 1, N'Air Jordan 4 Retro "White Cement"', N'網格側板、鞋帶翼片與可視氣墊定義了 1989 年的經典。白色皮革搭配灰色爆裂紋，簡潔又有層次，好搭不挑人。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (4, 2, 1, N'Air Jordan 11 Retro "Concord"', N'史上第一雙使用漆皮的籃球鞋。白色鞋身搭配黑色漆皮與冰藍大底，陪伴公牛寫下 72 勝傳奇，兼具球場性能與優雅質感。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (5, 1, 1, N'Nike Kobe 6 Protro "Grinch"', N'Kobe 在 2010 年聖誕大戰穿上的螢光綠戰靴。鱗片紋理呼應黑曼巴精神，Protro 版本升級現代緩震，經典也能真正上場。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (6, 1, 1, N'Nike G.T. Cut 3', N'為講求速度的後衛打造。ZoomX 泡棉中底輕量又回彈，低筒貼地設計讓急停、變向與啟動更直接俐落。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (7, 3, 1, N'adidas Anthony Edwards 1', N'Anthony Edwards 首雙簽名鞋。立體網格外殼提供穩定支撐並保有透氣性，黑紅配色搶眼，就像 Ant 一樣從不低調。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (8, 4, 1, N'New Balance TWO WXY v4', N'為全能型球員設計。輕量鞋面服貼包覆，FuelCell 中底帶來推進回彈，切入靈活、落地穩定，白銀配色低調俐落。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (9, 1, 2, N'Nike Pegasus 41', N'陪伴跑者超過 40 年的經典訓練鞋。ReactX 泡棉搭配前後掌 Air Zoom 氣墊，回彈更出色，日常慢跑一雙搞定。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (10, 1, 2, N'Nike Vomero 18', N'Vomero 系列以柔軟緩震著稱。ZoomX 與 ReactX 雙層泡棉，上層柔軟、下層穩定，長距離也能保持雙腿舒適。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (11, 1, 2, N'Nike Air Max 90', N'1990 年由 Tinker Hatfield 設計，放大的後跟氣墊窗讓它成為 Air Max 家族最具辨識度的一員。全白配色百搭不過時。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (12, 3, 2, N'adidas Ultraboost 5', N'Light BOOST 中底保留招牌彈跳感並更輕盈，搭配 Continental 橡膠大底，抓地力可靠。米色鞋身溫潤耐看。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (13, 3, 2, N'adidas Adizero Adios Pro 3', N'為馬拉松競速而生。Lightstrike Pro 中底內嵌 ENERGYRODS 推進結構，推蹬有力，幫助你在長距離中維持配速。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (14, 4, 2, N'New Balance Fresh Foam X 1080 v14', N'New Balance 旗艦緩震跑鞋。Fresh Foam X 中底柔軟又不失支撐，長距離訓練與日常慢跑都能輕鬆應對。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (15, 4, 2, N'New Balance 990v6', N'堅持美國製造的 990 系列第六代。FuelCell 中底回彈更好，搭配 ENCAP 支撐結構，元祖灰是最經典的配色。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (16, 4, 2, N'New Balance 2002R', N'以 2010 年高階跑鞋 MR2002 為藍本打造。ABZORB 與 N-ergy 中底兼顧緩震與支撐，灰色麂皮層次豐富。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (17, 1, 3, N'Nike Air Force 1 ''07', N'1982 年首雙搭載 Nike Air 的籃球鞋，從球場走向街頭四十多年。全白皮革乾淨俐落，是衣櫃裡不能少的小白鞋。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (18, 1, 3, N'Nike Dunk Low Retro "Panda"', N'1985 年為大學籃球隊誕生的 Dunk，如今是街頭文化的象徵。黑白雙色皮革拼接，簡單卻極具辨識度。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (19, 3, 3, N'adidas Samba OG', N'源自 1950 年代的足球訓練鞋。白色皮革搭配麂皮 T 字鞋頭與膠底，完整保留經典德訓鞋輪廓。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (20, 3, 3, N'adidas Stan Smith', N'以網球名將命名的經典鞋款。白色皮革搭配打孔三條線與綠色後跟，簡約低調，正式休閒都好駕馭。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (21, 3, 3, N'adidas Superstar', N'1969 年以籃球鞋登場，招牌貝殼鞋頭能保護腳趾。白色皮革搭配黑色三條線，歷久不衰的街頭經典。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (22, 3, 3, N'adidas Gazelle', N'1966 年推出的訓練鞋，因英倫街頭文化廣為人知。咖啡色麂皮搭配米白三條線與膠底，復古又耐看。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (23, 4, 3, N'New Balance 550', N'1989 年的籃球鞋，2020 年復刻後一推出就成為焦點。皮革鞋面搭配低筒鞋型，白綠配色帶有學院風格。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (24, 4, 3, N'New Balance 530', N'源自 1990 年代的復古跑鞋。銀色金屬光澤與網布拼接，搭配厚實中底，舒適好穿的老爹鞋代表款。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (25, 5, 4, N'Vans Old Skool', N'1977 年推出，Vans 第一雙加上側邊 Sidestripe 的鞋款。帆布與麂皮拼接搭配鬆餅大底，滑板街頭兩相宜。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (26, 5, 4, N'Vans Sk8-Hi', N'1978 年推出的高筒滑板鞋，保護腳踝又不失板感。側邊 Sidestripe 與鬆餅大底，搭配各種褲型都好看。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (27, 5, 4, N'Vans Authentic', N'Vans 在 1966 年賣出的第一款鞋。簡約低筒鞋型搭配鬆餅大底，橄欖綠麂皮鞋面質感沉穩。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (28, 5, 4, N'Vans Classic Slip-On "Checkerboard"', N'免綁鞋帶、穿脫方便的經典懶人鞋。黑白棋盤格是 Vans 最具代表性的圖案，隨性又有個性。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (29, 1, 4, N'Nike SB Dunk Low Pro', N'專為滑板改良的 Dunk。加厚鞋舌提升包覆，Zoom Air 鞋墊緩衝落地衝擊，黑色麂皮搭配膠底經典耐看。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (30, 1, 4, N'Nike SB Zoom Janoski OG+', N'職業滑手 Stefan Janoski 的簽名鞋。簡約圓頭鞋型搭配 Zoom Air 鞋墊，板感與舒適兼顧。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (31, 3, 4, N'adidas Busenitz Pro', N'以職業滑手 Dennis Busenitz 命名，靈感來自足球鞋，鞋型貼合、板感直接。可翻折的長鞋舌更耐磨。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (32, 4, 4, N'New Balance Numeric 480', N'New Balance 滑板系列，以 80 年代籃球鞋為靈感。麂皮鞋面搭配膠底，兼顧板感與日常穿搭。', N'ON_SALE', '2026-09-23 20:00:00.000', '2026-09-23 20:00:00.000'),
                                                                                                                        (33, 6, 2, N'ASICS GEL-Kayano 14', N'千禧年跑鞋復刻，金屬銀配色搭配 GEL 緩震，復古跑鞋風潮代表作。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (34, 6, 2, N'ASICS GEL-1130', N'2000 年代跑鞋鞋型，網布與皮革拼接，日常穿搭也很好配。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (35, 7, 3, N'Converse Chuck 70 Hi', N'經典高筒帆布鞋升級版，加厚鞋底與更耐用的帆布鞋面。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (36, 7, 4, N'Converse One Star Pro', N'麂皮鞋面搭配 CX 泡棉鞋墊，專為滑板設計的經典星星鞋款。', N'DRAFT', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (37, 8, 3, N'Puma Suede Classic', N'1968 年誕生的麂皮經典，街頭與嘻哈文化的代表鞋款。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (38, 8, 3, N'Puma Palermo', N'源自 80 年代足球看台文化，T 字鞋頭搭配膠底，復古德訓風格。', N'OFF_SHELF', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (39, 2, 1, N'Air Jordan 5 Retro "Fire Red"', N'1990 年經典配色，反光 3M 鞋舌與鯊魚齒中底，戰鬥機造型設計。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (40, 2, 3, N'Air Jordan 1 Low OG "Reverse Mocha"', N'聯名款倒勾設計，米白與咖啡麂皮拼接，發售即秒殺的話題鞋款。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (41, 5, 4, N'Vans Knu Skool', N'Old Skool 的 90 年代加厚版，膨鬆鞋舌與立體側邊條紋。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (42, 5, 4, N'Vans Half Cab', N'滑板傳奇 Steve Caballero 簽名鞋，中筒設計兼顧保護與靈活。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-26 19:40:39.000'),
                                                                                                                        (43, 1, 3, N'Nike Killshot 2 Leather', N'70 年代網球鞋復刻，白色皮革搭配深藍勾勾與膠底，簡約百搭。', N'DRAFT', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (44, 9, 2, N'HOKA Clifton 9', N'輕量厚底緩震跑鞋，長距離慢跑與日常通勤都舒適。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (45, 9, 2, N'HOKA Bondi 8', N'HOKA 緩震最厚的旗艦跑鞋，腳感柔軟、適合長時間站立行走。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (46, 10, 2, N'On Cloudmonster', N'超大 CloudTec 雲朵中底，回彈明顯，外型辨識度極高。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (47, 10, 3, N'On Cloud 5', N'快穿鞋帶設計，輕巧好穿脫，城市日常與旅行的百搭款。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (48, 11, 2, N'Salomon XT-6', N'越野跑鞋出身，機能鞋帶與抓地大底，近年機能穿搭的代表鞋款。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (49, 11, 2, N'Salomon ACS Pro', N'融合越野性能與千禧年設計，穩定支撐搭配機能風外型。', N'DRAFT', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (50, 12, 3, N'Reebok Club C 85', N'簡約網球鞋型，軟皮鞋面搭配綠色 Logo，乾淨百搭。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (51, 12, 1, N'Reebok Question Mid', N'Allen Iverson 首雙簽名鞋，蜂巢氣墊與珠光鞋頭，90 年代籃球經典。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (52, 13, 3, N'Onitsuka Tiger Mexico 66', N'1966 年誕生的經典鞋款，黃黑配色與虎爪紋，日系復古代表。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (53, 14, 2, N'Saucony Shadow 6000', N'80 年代復古跑鞋，麂皮與網布拼接，層次豐富的配色設計。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (54, 1, 2, N'Nike Air Max 1 ''86 OG', N'首雙可視氣墊鞋款的 86 年原版復刻，大氣墊窗口設計。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (55, 1, 2, N'Nike Vomero 5', N'千禧年跑鞋美學，網布與塑料支撐片層層堆疊，復古機能風。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (56, 1, 4, N'Nike SB Force 58', N'滑板專用鞋款，融合 Air Force 1 鞋型與杯底耐磨設計，好踩又耐穿。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (57, 3, 3, N'adidas Forum Low', N'80 年代籃球鞋出身，腳踝綁帶與交叉鞋面設計，街頭復古經典。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (58, 3, 4, N'adidas Campus 00s', N'經典 Campus 加厚版，胖鞋舌與寬鞋型，滑板與街頭風格兼具。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (59, 3, 3, N'adidas Handball Spezial', N'手球鞋出身的復古鞋款，麂皮鞋面搭膠底，英倫球迷文化代表。', N'OFF_SHELF', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (60, 4, 1, N'New Balance 650', N'550 的高筒版本，皮革鞋面搭配復古籃球鞋型，90 年代球場風格。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
                                                                                                                        (61, 4, 2, N'New Balance 1906R', N'2000 年代跑鞋復刻，金屬銀配色與 N-ERGY 緩震，千禧跑鞋風格代表。', N'ON_SALE', '2026-09-25 18:48:52.000', '2026-09-25 18:48:52.000'),
